        if len(word) % 2 == 0:
            mid = len(word) // 2
            return word[:mid][::-1] + word[mid:][::-1]
        else:
            mid = len(word) // 2
            return word[:mid][::-1] + word[mid] + word[mid+1:][::-1]

    words = x.split()
